import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S08/S08E21.html","title":"S08E21 The One with the Cooking Class","lang":"zh-CN","frontmatter":{"title":"S08E21 The One with the Cooking Class","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":191},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":33.66,"words":10098},"filePathRelative":"语言/英语/Friends老友记/S08/S08E21.md"}`),l={name:`S08E21.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=a(`h1`,{id:`the-one-with-the-cooking-class`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#the-one-with-the-cooking-class`},[a(`span`,null,`The One with the Cooking Class`)])],-1),c[1]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`烹饪课`)])],-1),c[2]||=a(`p`,null,`The One With The Cooking Class`,-1),c[3]||=a(`blockquote`,null,[a(`p`,null,`烹饪班的那个`)],-1),r(p,{src:`/audio/friends/S08/S08E21/001.mp3`}),c[4]||=i(),c[5]||=a(`strong`,null,`Teleplay by:`,-1),c[6]||=i(` Brian Buckner & Sebastian Jones`,-1),c[7]||=a(`blockquote`,null,[a(`p`,null,`布莱恩·巴克纳和塞巴斯蒂安·琼斯`)],-1),r(p,{src:`/audio/friends/S08/S08E21/002.mp3`}),c[8]||=t(` <strong>Story by:</strong> Dana Klein Borkow<blockquote><p>Dana Klein Borkow</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Central Perk, everyone is there except Monica as Ross enters carrying a huge stack of newspapers.</em></p><blockquote><p>🎬 <em>中央公园，除了莫妮卡，所有人都在那里，罗斯拿着一大摞报纸走进来。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E21/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Ross Geller:`,-1),c[11]||=i(` Hey you guys I got some bad news. (He sets the stack of papers down on the table.)`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`嘿，伙计们，我有个坏消息。（他把一叠文件放在桌子上。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[15]||=i(` Well that’s no way to sell newspapers. Why don’t you try, "Extra! Extra! Read all about it!"`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`那可不是卖报纸的好办法。你为什么不试试，“额外的！额外的！阅读所有关于它的内容！”`)],-1),r(p,{src:`/audio/friends/S08/S08E21/005.mp3`}),c[17]||=i(),c[18]||=a(`strong`,null,`Ross Geller:`,-1),c[19]||=i(` No, Monica’s restaurant got a horrible review in the Post. (They all gasp.) I didn’t want her to see it, so I ran around the neighborhood and bought all the copies I could find. (He hands the paper to Phoebe and they all read it.)`,-1),c[20]||=a(`blockquote`,null,[a(`p`,null,`不，莫妮卡的餐厅在邮报上得到了一个糟糕的评论。（他们都喘着粗气）我不想让她看到，所以我在附近跑来跑去，买了我能找到的所有副本。（他把报纸递给菲比，他们都看了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/006.mp3`}),c[21]||=i(),c[22]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[23]||=i(` Man, this is bad! And I’ve had my share of bad reviews. I still remember my first good one though. (Quoting) "Everything else in this production of Our Town was simply terrible. Joey Tribbiani was abysmal."`,-1),c[24]||=a(`blockquote`,null,[a(`p`,null,`伙计，这太糟糕了！我也有过一些不好的评论。我仍然记得我的第一个好的。（引用）“我们镇上的其他一切都很糟糕，乔伊·特里比亚尼简直糟透了。”`)],-1),r(p,{src:`/audio/friends/S08/S08E21/007.mp3`}),c[25]||=i(),c[26]||=a(`strong`,null,`Monica Geller:`,-1),c[27]||=i(` (entering) Hey!`,-1),c[28]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/008.mp3`}),c[29]||=i(),c[30]||=a(`strong`,null,`Chandler Bing:`,-1),c[31]||=i(` Hey.`,-1),c[32]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/009.mp3`}),c[33]||=i(),c[34]||=a(`strong`,null,`Monica Geller:`,-1),c[35]||=i(` (seeing the stack of newspapers) Oh my God! Look at all the newspapers! It must be a good review! Is it great?!`,-1),c[36]||=a(`blockquote`,null,[a(`p`,null,`（看到那堆报纸）哦，天哪！看看所有的报纸！这一定是一次很好的复习！很棒吗？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/010.mp3`}),c[37]||=i(),c[38]||=a(`strong`,null,`Ross Geller:`,-1),c[39]||=i(` Umm…`,-1),c[40]||=a(`blockquote`,null,[a(`p`,null,`嗯…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/011.mp3`}),c[41]||=i(),c[42]||=a(`strong`,null,`Monica Geller:`,-1),c[43]||=i(` (reading) Oh dear God!`,-1),c[44]||=a(`blockquote`,null,[a(`p`,null,`（读）哦，天哪！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/012.mp3`}),c[45]||=i(),c[46]||=a(`strong`,null,`Ross Geller:`,-1),c[47]||=i(` But the good news is, no one in a two-block radius will ever know.`,-1),c[48]||=a(`blockquote`,null,[a(`p`,null,`但好消息是，在两个街区半径内没有人会知道。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/013.mp3`}),c[49]||=i(),c[50]||=a(`strong`,null,`Monica Geller:`,-1),c[51]||=i(` What about the rest of Manhattan?!`,-1),c[52]||=a(`blockquote`,null,[a(`p`,null,`那曼哈顿的其他地方呢？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/014.mp3`}),c[53]||=i(),c[54]||=a(`strong`,null,`Ross Geller:`,-1),c[55]||=i(` Yeah, they all know.`,-1),c[56]||=a(`blockquote`,null,[a(`p`,null,`是的，他们都知道。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/015.mp3`}),c[57]||=i(),c[58]||=a(`strong`,null,`Monica Geller:`,-1),c[59]||=i(` Oh my God, this is horrible!`,-1),c[60]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，这太可怕了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/016.mp3`}),c[61]||=i(),c[62]||=a(`strong`,null,`Chandler Bing:`,-1),c[63]||=i(` I’m so sorry.`,-1),c[64]||=a(`blockquote`,null,[a(`p`,null,`我很抱歉。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/017.mp3`}),c[65]||=i(),c[66]||=a(`strong`,null,`Monica Geller:`,-1),c[67]||=i(` I’m so humiliated!`,-1),c[68]||=a(`blockquote`,null,[a(`p`,null,`我太丢脸了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/018.mp3`}),c[69]||=i(),c[70]||=a(`strong`,null,`Rachel Green:`,-1),c[71]||=i(` Yeah but y’know what they say Mon, "There’s no such thing as bad press."`,-1),c[72]||=a(`blockquote`,null,[a(`p`,null,`是的，但你知道他们怎么说吗，莫，“没有坏消息。”`)],-1),r(p,{src:`/audio/friends/S08/S08E21/019.mp3`}),c[73]||=i(),c[74]||=a(`strong`,null,`Monica Geller:`,-1),c[75]||=i(` You don’t think that umm, (reading) "The chef’s Mahi Mahi was awful awful," is bad press?`,-1),c[76]||=a(`blockquote`,null,[a(`p`,null,`你不认为，嗯，（读着）“厨师的麻辣酱太糟糕了”是坏消息吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/020.mp3`}),c[77]||=i(),c[78]||=a(`strong`,null,`Rachel Green:`,-1),c[79]||=i(` I didn’t write it.`,-1),c[80]||=a(`blockquote`,null,[a(`p`,null,`不是我写的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/021.mp3`}),c[81]||=i(),c[82]||=a(`strong`,null,`Monica Geller:`,-1),c[83]||=i(` Is he right? Am I really—Am I awful?`,-1),c[84]||=a(`blockquote`,null,[a(`p`,null,`他说得对吗？我真的很糟糕吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/022.mp3`}),c[85]||=i(),c[86]||=a(`strong`,null,`All:`,-1),c[87]||=i(` No!`,-1),c[88]||=a(`blockquote`,null,[a(`p`,null,`不！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/023.mp3`}),c[89]||=t(` <strong>Joey Tribbiani:</strong> Yeah! Yeah Monica! You listen to me, okay? And I’m not just saying this because I’m your friend, I’m sayin’ it ‘cause it’s the truth. You’re food is abysmal!<blockquote><p>是啊！是的，莫妮卡！你听我说，好吗？我这么说不仅仅是因为我是你的朋友，我这么说是因为这是事实。你的食物糟透了！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Ross and Rachel&#39;s, it’s late at night, Rachel is sitting on the couch in the dark wide-awake as Ross walks to the bathroom.</em></p><blockquote><p>🎬 <em>罗斯和瑞秋家，已经很晚了，瑞秋在黑暗中坐在沙发上，醒着，罗斯走向浴室。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E21/024.mp3`}),c[90]||=i(),c[91]||=a(`strong`,null,`Rachel Green:`,-1),c[92]||=i(` Ross!`,-1),c[93]||=a(`blockquote`,null,[a(`p`,null,`罗斯！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/025.mp3`}),c[94]||=i(),c[95]||=a(`strong`,null,`Ross Geller:`,-1),c[96]||=i(` (startling him) What?! What?`,-1),c[97]||=a(`blockquote`,null,[a(`p`,null,`（吓了他一跳）什么？！什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/026.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`Rachel Green:`,-1),c[100]||=i(` I am freaking out!`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`我吓坏了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/027.mp3`}),c[102]||=i(),c[103]||=a(`strong`,null,`Ross Geller:`,-1),c[104]||=i(` Are ya?`,-1),c[105]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/028.mp3`}),c[106]||=i(),c[107]||=a(`strong`,null,`Rachel Green:`,-1),c[108]||=i(` My due date is in one week!`,-1),c[109]||=a(`blockquote`,null,[a(`p`,null,`我的预产期还有一周！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/029.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`Ross Geller:`,-1),c[112]||=i(` What are you doing up?`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`你在干什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/030.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Rachel Green:`,-1),c[116]||=i(` That is seven days!`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`那是七天！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/031.mp3`}),c[118]||=i(),c[119]||=a(`strong`,null,`Ross Geller:`,-1),c[120]||=i(` Okay look, I had a lot of water before I went to bed. Can we do this after…`,-1),c[121]||=a(`blockquote`,null,[a(`p`,null,`好吧，听着，我睡觉前喝了很多水。我们可以在…之后再做吗…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/032.mp3`}),c[122]||=i(),c[123]||=a(`strong`,null,`Rachel Green:`,-1),c[124]||=i(` (interrupting him) No-no-no-no-no Ross! Please, come on we do not have any of the big stuff we need! We do not a changing table! We do not have a crib! We do not have a diaper service!`,-1),c[125]||=a(`blockquote`,null,[a(`p`,null,`（打断他）不，不，罗斯！拜托，快点，我们没有我们需要的任何大东西！我们不需要换桌子！我们没有婴儿床！我们没有尿布服务！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/033.mp3`}),c[126]||=i(),c[127]||=a(`strong`,null,`Ross Geller:`,-1),c[128]||=i(` It’s funny you should mention diapers.`,-1),c[129]||=a(`blockquote`,null,[a(`p`,null,`有趣的是你竟然提到尿布。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/034.mp3`}),c[130]||=i(),c[131]||=a(`strong`,null,`Rachel Green:`,-1),c[132]||=i(` I’m serious.`,-1),c[133]||=a(`blockquote`,null,[a(`p`,null,`我是认真的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/035.mp3`}),c[134]||=i(),c[135]||=a(`strong`,null,`Ross Geller:`,-1),c[136]||=i(` Okay look, there’s nothing to worry about. We have plenty of time. There’s a great baby furniture store on west 10th. Tomorrow, we will go there and we will get you everything that you need. Okay?`,-1),c[137]||=a(`blockquote`,null,[a(`p`,null,`好吧，听着，没什么好担心的。我们有足够的时间。西10街有一家很棒的婴儿家具店。明天，我们将去那里，我们将为您提供您需要的一切。可以`)],-1),r(p,{src:`/audio/friends/S08/S08E21/036.mp3`}),c[138]||=i(),c[139]||=a(`strong`,null,`Rachel Green:`,-1),c[140]||=i(` Okay. Thank you. That’s great. Thank you. Wait-wait! Where on west 10th? Because there’s this really cute shoe store that has like this little…`,-1),c[141]||=a(`blockquote`,null,[a(`p`,null,`好的。非常感谢。太好了。非常感谢。等等，等等！西10号在哪里？因为有一家非常可爱的鞋店，它有一个小…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/037.mp3`}),c[142]||=i(),c[143]||=a(`strong`,null,`Ross Geller:`,-1),c[144]||=i(` (interrupting her) Okay. Okay. If uh, if you’re gonna do this, then I’m gonna do that. (Points to the bathroom.) So… (Starts for the bathroom.)`,-1),c[145]||=a(`blockquote`,null,[a(`p`,null,`（打断她）好的。可以如果你要这么做，我也要这么做。（指向浴室。）那么…（从浴室开始。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/038.mp3`}),c[146]||=i(),c[147]||=a(`strong`,null,`Rachel Green:`,-1),c[148]||=i(` (stopping him) Oh, wait Ross! I’m sorry, one more thing!`,-1),c[149]||=a(`blockquote`,null,[a(`p`,null,`（阻止他）哦，等等，罗斯！对不起，还有一件事！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/039.mp3`}),c[150]||=i(),c[151]||=a(`strong`,null,`Ross Geller:`,-1),c[152]||=i(` (annoyed) Yeah!`,-1),c[153]||=a(`blockquote`,null,[a(`p`,null,`（生气）是啊！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/040.mp3`}),c[154]||=i(),c[155]||=a(`strong`,null,`Rachel Green:`,-1),c[156]||=i(` Umm, our situation. Y’know umm, what we mean to each other. And I mean we-we’re having this baby together, and we live together. Isn’t that, isn’t that weird?`,-1),c[157]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们的情况。你知道我们对彼此意味着什么。我的意思是我们一起生孩子，一起生活。这不是很奇怪吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/041.mp3`}),c[158]||=i(),c[159]||=a(`strong`,null,`Ross Geller:`,-1),c[160]||=i(` (stunned) (thinks) Well uh…`,-1),c[161]||=a(`blockquote`,null,[a(`p`,null,`（惊呆了）（想）嗯…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/042.mp3`}),c[162]||=i(),c[163]||=a(`strong`,null,`Rachel Green:`,-1),c[164]||=i(` I’m just kidding! You can go pee! (He does so in a hurry.)`,-1),c[165]||=a(`blockquote`,null,[a(`p`,null,`我只是开玩笑！你可以去小便！（他这么做很匆忙。）`)],-1),c[166]||=a(`p`,null,`[Scene: Monica and Chandler's, Monica is cooking as Chandler looks on.`,-1),r(p,{src:`/audio/friends/S08/S08E21/043.mp3`}),c[167]||=i(),c[168]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[169]||=i(` (entering) Hey uh Monica, I can’t remember. Did we say we were gonna meet here or at the movies?`,-1),c[170]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，嗯，莫妮卡，我不记得了。我们是说我们要在这里见面还是在电影院见面？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/044.mp3`}),c[171]||=i(),c[172]||=a(`strong`,null,`Monica Geller:`,-1),c[173]||=i(` We said at the movies, but…`,-1),c[174]||=a(`blockquote`,null,[a(`p`,null,`我们在电影里说过，但是…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/045.mp3`}),c[175]||=i(),c[176]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[177]||=i(` Okay, I’ll see you there. (Starts to leave)`,-1),c[178]||=a(`blockquote`,null,[a(`p`,null,`好的，我们在那儿见。（开始离开）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/046.mp3`}),c[179]||=i(),c[180]||=a(`strong`,null,`Monica Geller:`,-1),c[181]||=i(` Joey! (He returns) Now that you’re here…`,-1),c[182]||=a(`blockquote`,null,[a(`p`,null,`乔伊！（他回来）既然你来了…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/047.mp3`}),c[183]||=i(),c[184]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[185]||=i(` Sure, I can hang out ‘til I have to meet ya. (To Chandler) What uh—How come you’re not going?`,-1),c[186]||=a(`blockquote`,null,[a(`p`,null,`当然，我可以一直呆到要见你。（对钱德勒）你怎么不去？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/048.mp3`}),c[187]||=i(),c[188]||=a(`strong`,null,`Chandler Bing:`,-1),c[189]||=i(` I have a job interview I have to get ready for.`,-1),c[190]||=a(`blockquote`,null,[a(`p`,null,`我有一个工作面试要准备。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/049.mp3`}),c[191]||=i(),c[192]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[193]||=i(` I thought you already have a job.`,-1),c[194]||=a(`blockquote`,null,[a(`p`,null,`我以为你已经有工作了。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/050.mp3`}),c[195]||=i(),c[196]||=a(`strong`,null,`Chandler Bing:`,-1),c[197]||=i(` And people say you don’t pay attention. No, this is a much better job. It’s vice-president of a company that does data reconfiguration and statistical factoring for other companies.`,-1),c[198]||=a(`blockquote`,null,[a(`p`,null,`人们说你不注意。不，这是一份更好的工作。它是一家为其他公司进行数据重新配置和统计分解的公司的副总裁。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/051.mp3`}),c[199]||=i(),c[200]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[201]||=i(` Wow! How do you know how to do that?!`,-1),c[202]||=a(`blockquote`,null,[a(`p`,null,`哇！你怎么知道怎么做？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/052.mp3`}),c[203]||=i(),c[204]||=a(`strong`,null,`Chandler Bing:`,-1),c[205]||=i(` That’s what I do now.`,-1),c[206]||=a(`blockquote`,null,[a(`p`,null,`我现在就是这么做的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/053.mp3`}),c[207]||=i(),c[208]||=a(`strong`,null,`Monica Geller:`,-1),c[209]||=i(` Hey Joey, come taste this.`,-1),c[210]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔伊，来尝尝这个。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/054.mp3`}),c[211]||=i(),c[212]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[213]||=i(` What is it?`,-1),c[214]||=a(`blockquote`,null,[a(`p`,null,`什么事？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/055.mp3`}),c[215]||=i(),c[216]||=a(`strong`,null,`Monica Geller:`,-1),c[217]||=i(` Remember that guy that gave me a bad review? Well… (Feeds him a spoonful of what she’s cooking.) I’m getting my revenge!`,-1),c[218]||=a(`blockquote`,null,[a(`p`,null,`还记得那个给我坏评价的家伙吗？嗯…（喂了他一匙她做的东西。）我要报仇了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/056.mp3`}),c[219]||=i(),c[220]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[221]||=i(` You cooked him?`,-1),c[222]||=a(`blockquote`,null,[a(`p`,null,`你煮了他？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/057.mp3`}),c[223]||=i(),c[224]||=a(`strong`,null,`Monica Geller:`,-1),c[225]||=i(` No. He teaches a course on food criticism at the New School, so before we go to the movies I wanna go by there and make him try my bouillabaisse again. Oh, I cannot wait to read the front page of the Post tomorrow! "Restaurant reviewer admits: I was wrong about Monica."`,-1),c[226]||=a(`blockquote`,null,[a(`p`,null,`没有。他在新学校教一门关于食物批评的课程，所以在我们去看电影之前，我想去那里让他再尝尝我的肉汤。哦，我迫不及待地想明天读这篇文章的头版！”餐馆评论员承认：我对莫妮卡的看法是错误的`)],-1),r(p,{src:`/audio/friends/S08/S08E21/058.mp3`}),c[227]||=i(),c[228]||=a(`strong`,null,`Chandler Bing:`,-1),c[229]||=i(` The front page? You really do live in your own little world, don’t ya?`,-1),c[230]||=a(`blockquote`,null,[a(`p`,null,`头版？你真的生活在你自己的小世界里，不是吗？`)],-1),c[231]||=a(`hr`,null,null,-1),c[232]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Baby Furniture Store, Ross and Rachel are checking out.`)],-1),c[233]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`婴儿家具店，罗斯和瑞秋正在退房。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/059.mp3`}),c[234]||=i(),c[235]||=a(`strong`,null,`Cashier:`,-1),c[236]||=i(` Do you uh, want these things delivered Mr. and Mrs. Geller?`,-1),c[237]||=a(`blockquote`,null,[a(`p`,null,`你想让盖勒夫妇把这些东西送到吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/060.mp3`}),c[238]||=i(),c[239]||=a(`strong`,null,`Rachel Green:`,-1),c[240]||=i(` Oh.`,-1),c[241]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/061.mp3`}),c[242]||=i(),c[243]||=a(`strong`,null,`Ross Geller:`,-1),c[244]||=i(` Oh.`,-1),c[245]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/062.mp3`}),c[246]||=i(),c[247]||=a(`strong`,null,`Rachel Green:`,-1),c[248]||=i(` No-no-no! No, no, no, we’re not married.`,-1),c[249]||=a(`blockquote`,null,[a(`p`,null,`不，不，不，不，我们还没结婚。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/063.mp3`}),c[250]||=i(),c[251]||=a(`strong`,null,`Ross Geller:`,-1),c[252]||=i(` We are having a baby together, but we’re not involved. (The cashier, a very beautiful woman, looks confused) I mean, uh we-we were seeing each other a while ago, but then we were just friends. And then there was one drunken night. (Rachel looks at him angrily) Or, yes stranger, we’d like this delivered please.`,-1),c[253]||=a(`blockquote`,null,[a(`p`,null,`我们要生个孩子，但我们没有牵连。（出纳员，一个非常漂亮的女人，看起来很困惑）我的意思是，呃，我们刚才还见过面，但那时我们只是朋友。然后有一个晚上喝醉了。（瑞秋生气地看着他）或者，是的，陌生人，我们想送这个。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/064.mp3`}),c[254]||=i(),c[255]||=a(`strong`,null,`Cashier:`,-1),c[256]||=i(` Why don’t you fill out this address card. (Hands him one.)`,-1),c[257]||=a(`blockquote`,null,[a(`p`,null,`你何不填一下这张地址卡。（递给他一张。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/065.mp3`}),c[258]||=i(),c[259]||=a(`strong`,null,`Ross Geller:`,-1),c[260]||=i(` Oh, okay.`,-1),c[261]||=a(`blockquote`,null,[a(`p`,null,`哦，好的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/066.mp3`}),c[262]||=i(),c[263]||=a(`strong`,null,`Cashier:`,-1),c[264]||=i(` I notice you picked out a lot of our dinosaur items.`,-1),c[265]||=a(`blockquote`,null,[a(`p`,null,`我注意到你挑了很多我们的恐龙用品。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/067.mp3`}),c[266]||=i(),c[267]||=a(`strong`,null,`Rachel Green:`,-1),c[268]||=i(` Oh yeah! Actually, that’s one of the reasons why we’re not a couple.`,-1),c[269]||=a(`blockquote`,null,[a(`p`,null,`哦，是啊！事实上，这就是我们不是夫妻的原因之一。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/068.mp3`}),c[270]||=i(),c[271]||=a(`strong`,null,`Ross Geller:`,-1),c[272]||=i(` I chose those, I’m a paleontologist.`,-1),c[273]||=a(`blockquote`,null,[a(`p`,null,`是我选的，我是古生物学家。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/069.mp3`}),c[274]||=i(),c[275]||=a(`strong`,null,`Cashier:`,-1),c[276]||=i(` Really?! That is so cool!`,-1),c[277]||=a(`blockquote`,null,[a(`p`,null,`真的吗？太酷了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/070.mp3`}),c[278]||=i(),c[279]||=a(`strong`,null,`Rachel Green:`,-1),c[280]||=i(` Oh. Oh yeah, don’t get to worked up over it. I mean it-it sounds like he’s a doctor, but he’s not.`,-1),c[281]||=a(`blockquote`,null,[a(`p`,null,`哦。哦，是的，别为此而激动。我的意思是，听起来他好像是个医生，但他不是。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/071.mp3`}),c[282]||=i(),c[283]||=a(`strong`,null,`Cashier:`,-1),c[284]||=i(` Oh no-no, I’m fascinated by paleontology. Have you read the new Walter Alvarez book?`,-1),c[285]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，我对古生物学很着迷。你读过沃尔特·阿尔瓦雷斯的新书吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/072.mp3`}),c[286]||=i(),c[287]||=a(`strong`,null,`Ross Geller:`,-1),c[288]||=i(` Yeah! I-I teach it in my class.`,-1),c[289]||=a(`blockquote`,null,[a(`p`,null,`是啊！我在课堂上教。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/073.mp3`}),c[290]||=i(),c[291]||=a(`strong`,null,`Rachel Green:`,-1),c[292]||=i(` Oh my God! I’m standing at a cash register, holding a credit card, and I’m bored.`,-1),c[293]||=a(`blockquote`,null,[a(`p`,null,`我的天啊！我站在收银机旁，手里拿着一张信用卡，我很无聊。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/074.mp3`}),c[294]||=i(),c[295]||=a(`strong`,null,`Cashier:`,-1),c[296]||=i(` (looking at the completed address card) Oh, I love your neighborhood. There’s a great gym right around the corner from your building.`,-1),c[297]||=a(`blockquote`,null,[a(`p`,null,`（看着填好的地址卡）哦，我喜欢你的社区。在你的大楼拐角处有一个很棒的健身房。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/075.mp3`}),c[298]||=i(),c[299]||=a(`strong`,null,`Ross Geller:`,-1),c[300]||=i(` That’s my gym.`,-1),c[301]||=a(`blockquote`,null,[a(`p`,null,`那是我的健身房。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/076.mp3`}),c[302]||=i(),c[303]||=a(`strong`,null,`Cashier:`,-1),c[304]||=i(` I can tell you work out. (Ross is please and Rachel looks at him confused.) A paleontologist who works out, you’re like Indiana Jones. (Rachel has a disbelieving look on her face.)`,-1),c[305]||=a(`blockquote`,null,[a(`p`,null,`我可以告诉你锻炼。（罗斯很高兴，瑞秋困惑地看着他。）一个锻炼的古生物学家，你就像印第安纳·琼斯。（瑞秋脸上带着不相信的表情。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/077.mp3`}),c[306]||=i(),c[307]||=a(`strong`,null,`Ross Geller:`,-1),c[308]||=i(` I am like Indiana Jones.`,-1),c[309]||=a(`blockquote`,null,[a(`p`,null,`我就像印第安纳琼斯。`)],-1),c[310]||=a(`hr`,null,null,-1),c[311]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Phoebe is there as Rachel enters.`)],-1),c[312]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，瑞秋进来时菲比在那里。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/078.mp3`}),c[313]||=i(),c[314]||=a(`strong`,null,`Rachel Green:`,-1),c[315]||=i(` Hi Pheebs!`,-1),c[316]||=a(`blockquote`,null,[a(`p`,null,`嗨，菲比！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/079.mp3`}),c[317]||=i(),c[318]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[319]||=i(` Hey! Oh, how did baby shopping go?`,-1),c[320]||=a(`blockquote`,null,[a(`p`,null,`嘿！哦，婴儿购物怎么样？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/080.mp3`}),c[321]||=i(),c[322]||=a(`strong`,null,`Rachel Green:`,-1),c[323]||=i(` Oh, it was great! We got everything that we needed! Oh and Ross, almost got something that wasn’t on the list. A whore.`,-1),c[324]||=a(`blockquote`,null,[a(`p`,null,`哦，太棒了！我们得到了我们需要的一切！哦，罗斯，几乎得到了清单上没有的东西。一个妓女。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/081.mp3`}),c[325]||=i(),c[326]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[327]||=i(` What?!`,-1),c[328]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/082.mp3`}),c[329]||=i(),c[330]||=a(`strong`,null,`Rachel Green:`,-1),c[331]||=i(` Well, we were paying for our stuff and this saleswoman just started flirting with him.`,-1),c[332]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们在为我们的东西付钱，而这个女售货员刚开始和他调情。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/083.mp3`}),c[333]||=i(),c[334]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[335]||=i(` Well did she know you two weren’t married?`,-1),c[336]||=a(`blockquote`,null,[a(`p`,null,`她知道你们俩没结婚吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/084.mp3`}),c[337]||=i(),c[338]||=a(`strong`,null,`Rachel Green:`,-1),c[339]||=i(` Yeah.`,-1),c[340]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/085.mp3`}),c[341]||=i(),c[342]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[343]||=i(` Oh my God! Well the idea of a woman flirting with a-with a single man, we-we must alert the church elders!`,-1),c[344]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天！一个女人和一个单身男人调情的想法，我们必须提醒教堂的长老们！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/086.mp3`}),c[345]||=i(),c[346]||=a(`strong`,null,`Rachel Green:`,-1),c[347]||=i(` You don’t understand! You didn’t see how brazen she was.`,-1),c[348]||=a(`blockquote`,null,[a(`p`,null,`你不明白！你没看到她有多厚颜无耻。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/087.mp3`}),c[349]||=i(),c[350]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[351]||=i(` Sounds like you’re a little jealous.`,-1),c[352]||=a(`blockquote`,null,[a(`p`,null,`听起来你有点嫉妒。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/088.mp3`}),c[353]||=i(),c[354]||=a(`strong`,null,`Rachel Green:`,-1),c[355]||=i(` No! I’m not! I-I-I just think it’s wrong! It’s-it’s that I’m—Here I am about to pop and he’s out picking up some shop girl at Sluts ‘R’ Us!`,-1),c[356]||=a(`blockquote`,null,[a(`p`,null,`不！我不是！我-我-我只是认为这是错的！是-是-我-我在这里，我要跳了，他出去在荡妇酒吧接女店员！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/089.mp3`}),c[357]||=i(),c[358]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[359]||=i(` Is that a real place? (Rachel’s stunned) Are they hiring?`,-1),c[360]||=a(`blockquote`,null,[a(`p`,null,`那是真的吗？（瑞秋惊呆了）他们在招聘吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/090.mp3`}),c[361]||=i(),c[362]||=a(`strong`,null,`Chandler Bing:`,-1),c[363]||=i(` (entering) Hey Phoebe! (To Rachel) Fatty!`,-1),c[364]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，菲比！（对瑞秋）胖子！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/091.mp3`}),c[365]||=i(),c[366]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[367]||=i(` Hey Chandler, why so fancy?`,-1),c[368]||=a(`blockquote`,null,[a(`p`,null,`嘿，钱德勒，为什么这么花哨？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/092.mp3`}),c[369]||=i(),c[370]||=a(`strong`,null,`Chandler Bing:`,-1),c[371]||=i(` Well, I got a job interview. It’s kinda a big deal too. Its a lot more money and I’d be doing data reconfiguration and statistical factoring.`,-1),c[372]||=a(`blockquote`,null,[a(`p`,null,`嗯，我有一个工作面试。这也有点大。它的钱要多得多，我会做数据重构和统计分解。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/093.mp3`}),c[373]||=i(),c[374]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[375]||=i(` Wait, I think I know someone who does that.`,-1),c[376]||=a(`blockquote`,null,[a(`p`,null,`等等，我想我认识这样做的人。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/094.mp3`}),c[377]||=i(),c[378]||=a(`strong`,null,`Chandler Bing:`,-1),c[379]||=i(` Me! I do that. So… Seriously, do I look okay? I’m little nervous.`,-1),c[380]||=a(`blockquote`,null,[a(`p`,null,`我！我就是这么做的。所以…说真的，我看起来还好吗？我有点紧张。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/095.mp3`}),c[381]||=i(),c[382]||=a(`strong`,null,`Rachel Green:`,-1),c[383]||=i(` Oh yeah! You really—You look great.`,-1),c[384]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！你真的看起来很棒。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/096.mp3`}),c[385]||=i(),c[386]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[387]||=i(` Yeah, just don’t get your hopes up.`,-1),c[388]||=a(`blockquote`,null,[a(`p`,null,`是啊，只是别抱太大希望。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/097.mp3`}),c[389]||=i(),c[390]||=a(`strong`,null,`Chandler Bing:`,-1),c[391]||=i(` Why not?`,-1),c[392]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/098.mp3`}),c[393]||=i(),c[394]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[395]||=i(` Well, the interview…`,-1),c[396]||=a(`blockquote`,null,[a(`p`,null,`嗯，面试…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/099.mp3`}),c[397]||=i(),c[398]||=a(`strong`,null,`Chandler Bing:`,-1),c[399]||=i(` What about it?`,-1),c[400]||=a(`blockquote`,null,[a(`p`,null,`怎么样？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/100.mp3`}),c[401]||=i(),c[402]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[403]||=i(` Y’know! You don’t make a very good first impression.`,-1),c[404]||=a(`blockquote`,null,[a(`p`,null,`你知道！你的第一印象不太好。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/101.mp3`}),c[405]||=i(),c[406]||=a(`strong`,null,`Chandler Bing:`,-1),c[407]||=i(` (shocked) What?!`,-1),c[408]||=a(`blockquote`,null,[a(`p`,null,`（震惊）什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/102.mp3`}),c[409]||=i(),c[410]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[411]||=i(` Oh you don’t know.`,-1),c[412]||=a(`blockquote`,null,[a(`p`,null,`哦，你不知道。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/103.mp3`}),c[413]||=i(),c[414]||=a(`strong`,null,`Chandler Bing:`,-1),c[415]||=i(` Are you serious?!`,-1),c[416]||=a(`blockquote`,null,[a(`p`,null,`你是认真的吗？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/104.mp3`}),c[417]||=i(),c[418]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[419]||=i(` Yes, when I first met you, you were like, "Blah, blah, blah." I was like, shhh!`,-1),c[420]||=a(`blockquote`,null,[a(`p`,null,`是的，当我第一次见到你的时候，你会说，“废话，废话。”我会说，嘘！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/105.mp3`}),c[421]||=i(),c[422]||=a(`strong`,null,`Chandler Bing:`,-1),c[423]||=i(` What is it that I do?`,-1),c[424]||=a(`blockquote`,null,[a(`p`,null,`我是做什么的？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/106.mp3`}),c[425]||=i(),c[426]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[427]||=i(` Well it’s just like you’re trying too hard. Always making jokes, y’know, you just—You come off a little needy.`,-1),c[428]||=a(`blockquote`,null,[a(`p`,null,`这就像你太努力了。你总是开玩笑，你知道，你只是有点需要。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/107.mp3`}),c[429]||=i(),c[430]||=a(`strong`,null,`Chandler Bing:`,-1),c[431]||=i(` (To Rachel) Did you like me when we first met?`,-1),c[432]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）我们第一次见面时你喜欢我吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/108.mp3`}),c[433]||=i(),c[434]||=a(`strong`,null,`Rachel Green:`,-1),c[435]||=i(` Chandler, I’m not gonna lie to ya, but I am gonna run away from you. (Gets up and hurries out.)`,-1),c[436]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，我不会对你撒谎，但我会从你身边跑开。（站起来赶紧出去。）`)],-1),c[437]||=a(`hr`,null,null,-1),c[438]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The New School, Monica, carrying her dish, and Joey are confronting the food critic.`)],-1),c[439]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`新学校，莫妮卡，端着她的菜，和乔伊面对着美食评论家。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/109.mp3`}),c[440]||=i(),c[441]||=a(`strong`,null,`Monica Geller:`,-1),c[442]||=i(` Hi! Umm, I’m Monica Geller, I’m the chef at Alessandro’s.`,-1),c[443]||=a(`blockquote`,null,[a(`p`,null,`嗨！嗯，我是莫妮卡·盖勒，我是亚历山德罗餐厅的厨师。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/110.mp3`}),c[444]||=i(),c[445]||=a(`strong`,null,`The Food Critic:`,-1),c[446]||=i(` Still?`,-1),c[447]||=a(`blockquote`,null,[a(`p`,null,`还是？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/111.mp3`}),c[448]||=i(),c[449]||=a(`strong`,null,`Monica Geller:`,-1),c[450]||=i(` I think the things that you said about me are really unfair, and I would like for you to give my bouillabaisse another chance.`,-1),c[451]||=a(`blockquote`,null,[a(`p`,null,`我觉得你说的关于我的话真的很不公平，我希望你再给我一次机会。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/112.mp3`}),c[452]||=i(),c[453]||=a(`strong`,null,`The Food Critic:`,-1),c[454]||=i(` I don’t see any reason why I would do that to myself again.`,-1),c[455]||=a(`blockquote`,null,[a(`p`,null,`我看不出有什么理由再这样对自己。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/113.mp3`}),c[456]||=i(),c[457]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[458]||=i(` Either eat it, or be in it.`,-1),c[459]||=a(`blockquote`,null,[a(`p`,null,`要么吃，要么在里面。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/114.mp3`}),c[460]||=i(),c[461]||=a(`strong`,null,`Monica Geller:`,-1),c[462]||=i(` Spoon? (Hands him one and he tastes it.) So, what do you think?`,-1),c[463]||=a(`blockquote`,null,[a(`p`,null,`勺子？（递给他一个，他尝了尝。）那么，你觉得呢？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/115.mp3`}),c[464]||=i(),c[465]||=a(`strong`,null,`The Food Critic:`,-1),c[466]||=i(` I’m torn, between my integrity and my desire to avoid a beating. But I must be honest, your soap is abysmal. (Throws down the spoon and walks out.)`,-1),c[467]||=a(`blockquote`,null,[a(`p`,null,`我被我的正直和避免挨揍的欲望所撕裂。但我必须诚实，你的肥皂糟透了。（扔下勺子走了出去。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/116.mp3`}),c[468]||=i(),c[469]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[470]||=i(` Thata girl! Huh? We should get out of here; there’s a new class comin’ in.`,-1),c[471]||=a(`blockquote`,null,[a(`p`,null,`那是个女孩！哈？我们应该离开这里，新班级来了。`)],-1),c[472]||=a(`p`,null,[a(`em`,null,`(They start to leave.)`)],-1),c[473]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们开始离开。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/117.mp3`}),c[474]||=i(),c[475]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[476]||=i(` Welcome to introduction to cooking. Now, before we start, can anyone tell me the difference between a hollandaise sauce and a bearnaise sauce? (No one can.)`,-1),c[477]||=a(`blockquote`,null,[a(`p`,null,`欢迎来到烹饪入门。现在，在我们开始之前，有人能告诉我荷兰酱和比尔奈酱的区别吗`)],-1),r(p,{src:`/audio/friends/S08/S08E21/118.mp3`}),c[478]||=i(),c[479]||=a(`strong`,null,`Monica Geller:`,-1),c[480]||=i(` I can.`,-1),c[481]||=a(`blockquote`,null,[a(`p`,null,`我可以。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/119.mp3`}),c[482]||=i(),c[483]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[484]||=i(` Okay, go ahead.`,-1),c[485]||=a(`blockquote`,null,[a(`p`,null,`好的，说吧。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/120.mp3`}),c[486]||=i(),c[487]||=a(`strong`,null,`Monica Geller:`,-1),c[488]||=i(` Well umm, they both have a egg yolk and butter base, but a bearnaise has shallots, shirvel, and most importantly tarragon.`,-1),c[489]||=a(`blockquote`,null,[a(`p`,null,`嗯，它们都有蛋黄和黄油，但熊泥有青葱、衬衫，最重要的是龙蒿。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/121.mp3`}),c[490]||=i(),c[491]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[492]||=i(` That’s very good, what’s your name?`,-1),c[493]||=a(`blockquote`,null,[a(`p`,null,`很好，你叫什么名字？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/122.mp3`}),c[494]||=i(),c[495]||=a(`strong`,null,`Monica Geller:`,-1),c[496]||=i(` Monica.`,-1),c[497]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/123.mp3`}),c[498]||=i(),c[499]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[500]||=i(` Monica, you go to the head of the class.`,-1),c[501]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡，你去班长那里。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/124.mp3`}),c[502]||=i(),c[503]||=a(`strong`,null,`Monica Geller:`,-1),c[504]||=i(` Okay. (Does so.)`,-1),c[505]||=a(`blockquote`,null,[a(`p`,null,`好的。（这样做。）`)],-1),c[506]||=a(`hr`,null,null,-1),c[507]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross and Rachel's, Ross and Rachel are unpacking and setting up their new purchases.`)],-1),c[508]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯和瑞秋家，罗斯和瑞秋正在打开包装，准备新的购买物品。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/125.mp3`}),c[509]||=i(),c[510]||=a(`strong`,null,`Rachel Green:`,-1),c[511]||=i(` All this stuff takes up a lot of room. Hey how uh, how serious are you about keeping Ben in your life?`,-1),c[512]||=a(`blockquote`,null,[a(`p`,null,`所有这些东西都占了很多空间。嘿，你对让本留在你的生活中有多认真？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/126.mp3`}),c[513]||=i(),c[514]||=a(`strong`,null,`Ross Geller:`,-1),c[515]||=i(` My son? Pretty serious. (There’s a knock on the door and Ross answers it.) Oh hey Katie! (The cashier from before) What uh, what are you doing here?`,-1),c[516]||=a(`blockquote`,null,[a(`p`,null,`我儿子？很认真。（有人敲门，罗斯应门。）哦，嘿，凯蒂！（以前的收银员）你在这里干什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/127.mp3`}),c[517]||=i(),c[518]||=a(`strong`,null,`Katie:`,-1),c[519]||=i(` Well, the delivery went out to you and I realized they forgot this. (A blanket.)`,-1),c[520]||=a(`blockquote`,null,[a(`p`,null,`嗯，送货给你了，我意识到他们忘了这个。（毯子）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/128.mp3`}),c[521]||=i(),c[522]||=a(`strong`,null,`Ross Geller:`,-1),c[523]||=i(` Ah, must’ve been fairly obvious since it was the only thing left in your store.`,-1),c[524]||=a(`blockquote`,null,[a(`p`,null,`啊，一定很明显，因为这是你们店里唯一剩下的东西。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/129.mp3`}),c[525]||=i(),c[526]||=a(`strong`,null,`Katie:`,-1),c[527]||=i(` Listen, to be honest, home deliveries are really a part of my job description.`,-1),c[528]||=a(`blockquote`,null,[a(`p`,null,`听着，老实说，送货上门真的是我工作描述的一部分。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/130.mp3`}),c[529]||=i(),c[530]||=a(`strong`,null,`Ross Geller:`,-1),c[531]||=i(` Oh. (Reaches into his pocket for some money as Rachel enters the living room and watches holding two stuffed dinosaurs.)`,-1),c[532]||=a(`blockquote`,null,[a(`p`,null,`噢。（当瑞秋走进客厅，看着手里拿着两只恐龙标本时，他把手伸进口袋拿了些钱。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/131.mp3`}),c[533]||=i(),c[534]||=a(`strong`,null,`Katie:`,-1),c[535]||=i(` Oh uh…I actually came here to ask you out.`,-1),c[536]||=a(`blockquote`,null,[a(`p`,null,`哦，嗯……我其实是来约你出去的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/132.mp3`}),c[537]||=i(),c[538]||=a(`strong`,null,`Ross Geller:`,-1),c[539]||=i(` Oh! Wow! Uh, yeah! That sounds great. I’m just gonna put this (The money) back in my pocket, pretend that didn’t happen. Uh yeah, actually I’m free now. Do you wanna grab some coffee or…`,-1),c[540]||=a(`blockquote`,null,[a(`p`,null,`哦！哇！嗯，是的！听起来不错。我只是想把钱放回口袋，假装没发生。嗯，是的，实际上我现在有空。你想喝点咖啡还是…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/133.mp3`}),c[541]||=i(),c[542]||=a(`strong`,null,`Katie:`,-1),c[543]||=i(` Sure!`,-1),c[544]||=a(`blockquote`,null,[a(`p`,null,`当然！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/134.mp3`}),c[545]||=t(` <strong>Rachel Green:</strong> Horny bitch. (They both look at her, pretending that the dinosaurs she’s holding are arguing.) No! You’re a horny bitch! Noooo! You’re the horny bitch! No! You’re a horny bitch!<blockquote><p>辣婊子。（他们都看着她，假装她抱着的恐龙在吵架。）不！你是辣婊子！不！你是辣婊子！不！你是辣婊子！</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Ross and Rachel&#39;s, continued from before.</em></p><blockquote><p>🎬 <em>罗斯和瑞秋的，从之前继续。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E21/135.mp3`}),c[546]||=i(),c[547]||=a(`strong`,null,`Rachel Green:`,-1),c[548]||=i(` So you guys go, have a really good time.`,-1),c[549]||=a(`blockquote`,null,[a(`p`,null,`你们走吧，玩得开心。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/136.mp3`}),c[550]||=i(),c[551]||=a(`strong`,null,`Ross Geller:`,-1),c[552]||=i(` (To Katie) Yeah, I’m just gonna grab my coat. And uh, and my whip. (Katie looks worried.) Y’know because of the Indiana Jones? (Katie laughs) Not-not because I’m-I’m into S&M. (Katie’s worried again.) I’m not-I’m not into anything weird. Y’know? Just-just normal sex. (Katie is uncomfortable.) So, I’m gonna grab my coat. (Does so, leaving Katie and Rachel alone.)`,-1),c[553]||=a(`blockquote`,null,[a(`p`,null,`（对凯蒂）是的，我只想拿我的外套。还有我的鞭子。（凯蒂看起来很担心。）你知道是因为印第安纳琼斯吗？（凯蒂笑）不是因为我-我喜欢S&m。（凯蒂又担心了。）我不-我不喜欢任何奇怪的事。你知道吗？只是正常的性行为。（凯蒂很不舒服。）所以，我要拿我的外套。（这样做了，留下凯蒂和瑞秋一个人。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/137.mp3`}),c[554]||=i(),c[555]||=a(`strong`,null,`Rachel Green:`,-1),c[556]||=i(` So, you had a good day huh? Big commission; picked up a daddy.`,-1),c[557]||=a(`blockquote`,null,[a(`p`,null,`那么，你今天过得很好，是吗？佣金很大；接了个爸爸。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/138.mp3`}),c[558]||=i(),c[559]||=a(`strong`,null,`Katie:`,-1),c[560]||=i(` Are you okay with this?`,-1),c[561]||=a(`blockquote`,null,[a(`p`,null,`你同意吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/139.mp3`}),c[562]||=i(),c[563]||=a(`strong`,null,`Rachel Green:`,-1),c[564]||=i(` Oh yeah! Yeah please, you guys have fun.`,-1),c[565]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！是的，拜托，你们玩得开心。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/140.mp3`}),c[566]||=i(),c[567]||=a(`strong`,null,`Katie:`,-1),c[568]||=i(` Okay. It was nice to see you.`,-1),c[569]||=a(`blockquote`,null,[a(`p`,null,`好的。很高兴见到你。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/141.mp3`}),c[570]||=i(),c[571]||=a(`strong`,null,`Rachel Green:`,-1),c[572]||=i(` Oh and it was great to see you too. And you look fantastic, although you missed a button.`,-1),c[573]||=a(`blockquote`,null,[a(`p`,null,`哦，见到你也很高兴。你看起来很棒，虽然你错过了一个按钮。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/142.mp3`}),c[574]||=i(),c[575]||=a(`strong`,null,`Katie:`,-1),c[576]||=i(` Oh umm, actually I umm…`,-1),c[577]||=a(`blockquote`,null,[a(`p`,null,`哦，嗯，实际上我嗯…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/143.mp3`}),c[578]||=i(),c[579]||=a(`strong`,null,`Rachel Green:`,-1),c[580]||=i(` Oh okay, I see what you’re doing there.`,-1),c[581]||=a(`blockquote`,null,[a(`p`,null,`哦，好吧，我明白你在那里做什么了。`)],-1),c[582]||=a(`hr`,null,null,-1),c[583]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Chandler's, Chandler and Phoebe are entering.`)],-1),c[584]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和钱德勒家，钱德勒和菲比进来了。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/144.mp3`}),c[585]||=i(),c[586]||=a(`strong`,null,`Chandler Bing:`,-1),c[587]||=i(` I can’t even believe this! I really come off that badly?`,-1),c[588]||=a(`blockquote`,null,[a(`p`,null,`我简直不敢相信！我真的那么糟糕？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/145.mp3`}),c[589]||=i(),c[590]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[591]||=i(` Oh! It’s okay, you calm down after a while and then people can see how really sweet and wonderful you really are.`,-1),c[592]||=a(`blockquote`,null,[a(`p`,null,`哦！没关系，过一会儿你冷静下来，然后人们就会看到你真的是多么的甜蜜和美妙。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/146.mp3`}),c[593]||=i(),c[594]||=a(`strong`,null,`Chandler Bing:`,-1),c[595]||=i(` Oh good. Good, because I’m sure this interview is gonna last a couple of weeks.`,-1),c[596]||=a(`blockquote`,null,[a(`p`,null,`哦，很好。很好，因为我肯定这次面试会持续几个星期。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/147.mp3`}),c[597]||=i(),c[598]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[599]||=i(` All right, don’t freak out! Okay? I-I will help you. How long before you have to leave?`,-1),c[600]||=a(`blockquote`,null,[a(`p`,null,`好吧，别紧张！好吗？我会帮你的。你还要多久才能离开？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/148.mp3`}),c[601]||=i(),c[602]||=a(`strong`,null,`Chandler Bing:`,-1),c[603]||=i(` An hour.`,-1),c[604]||=a(`blockquote`,null,[a(`p`,null,`一个小时。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/149.mp3`}),c[605]||=i(),c[606]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[607]||=i(` I can’t help you.`,-1),c[608]||=a(`blockquote`,null,[a(`p`,null,`我帮不了你。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/150.mp3`}),c[609]||=i(),c[610]||=a(`strong`,null,`Chandler Bing:`,-1),c[611]||=i(` Phoebe!`,-1),c[612]||=a(`blockquote`,null,[a(`p`,null,`菲比！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/151.mp3`}),c[613]||=i(),c[614]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[615]||=i(` All right, all right, we’ll just do our best. Okay? So let’s say I’m the interviewer and I’m meeting you for the first time. Okay. "Hi! Come on in, I’m uh, Regina Philange."`,-1),c[616]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，我们会尽力而为。好吗？假设我是面试官，我第一次见到你。好吧。“嗨！进来吧，我是里贾娜·菲兰奇。”`)],-1),r(p,{src:`/audio/friends/S08/S08E21/152.mp3`}),c[617]||=i(),c[618]||=a(`strong`,null,`Chandler Bing:`,-1),c[619]||=i(` Chandler Bing.`,-1),c[620]||=a(`blockquote`,null,[a(`p`,null,`钱德勒·宾。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/153.mp3`}),c[621]||=i(),c[622]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[623]||=i(` Bing, what an unusual name.`,-1),c[624]||=a(`blockquote`,null,[a(`p`,null,`宾，多不寻常的名字啊。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/154.mp3`}),c[625]||=i(),c[626]||=a(`strong`,null,`Chandler Bing:`,-1),c[627]||=i(` Well you should meet my uncle, Bada. (Pause) I’ll let myself out.`,-1),c[628]||=a(`blockquote`,null,[a(`p`,null,`你应该见见我叔叔，巴达。（停顿）我自己出去。`)],-1),c[629]||=a(`hr`,null,null,-1),c[630]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Cooking Class, Joey is trying to cook as the teacher walks over to him.`)],-1),c[631]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`烹饪课上，当老师走向乔伊时，乔伊正在试着做饭。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/155.mp3`}),c[632]||=i(),c[633]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[634]||=i(` Hi.`,-1),c[635]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/156.mp3`}),c[636]||=i(),c[637]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[638]||=i(` Your Fettuccini Alfredo looks a little dry, did you use all your cheese?`,-1),c[639]||=a(`blockquote`,null,[a(`p`,null,`你的费图奇尼·阿尔弗雷多看起来有点干，你把奶酪都用光了吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/157.mp3`}),c[640]||=i(),c[641]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[642]||=i(` When you say used, do you mean eat as a pre-cooking snack?`,-1),c[643]||=a(`blockquote`,null,[a(`p`,null,`当你说用过，你的意思是作为烹饪前的零食吃吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/158.mp3`}),c[644]||=i(),c[645]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[646]||=i(` And the cream?`,-1),c[647]||=a(`blockquote`,null,[a(`p`,null,`奶油呢？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/159.mp3`}),c[648]||=i(),c[649]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[650]||=i(` Cheese makes me thirsty.`,-1),c[651]||=a(`blockquote`,null,[a(`p`,null,`奶酪让我口渴。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/160.mp3`}),c[652]||=i(),c[653]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[654]||=i(` Okay. Let’s move on.`,-1),c[655]||=a(`blockquote`,null,[a(`p`,null,`好的，让我们继续。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/161.mp3`}),c[656]||=i(),c[657]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[658]||=i(` All right.`,-1),c[659]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/162.mp3`}),c[660]||=i(),c[661]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[662]||=i(` (To Monica) Oh! Something smells good over at Monica’s station! (She tries Monica’s fettuccini.) Oh my God! This is absolutely amazing! You’ve never made this before?`,-1),c[663]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）哦！莫妮卡车站的东西闻起来很香！（她试了试莫妮卡的费图奇尼。）哦，天哪！这太棒了！你以前从来没有做过这个？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/163.mp3`}),c[664]||=i(),c[665]||=a(`strong`,null,`Monica Geller:`,-1),c[666]||=i(` Oh no! I don’t know anything about cooking. I had to ask someone what it’s called when the, when the water makes those little bubbles.`,-1),c[667]||=a(`blockquote`,null,[a(`p`,null,`哦，不！我对烹饪一窍不通。我得问问别人，当水产生那些小泡泡的时候，它叫什么。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/164.mp3`}),c[668]||=i(),c[669]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[670]||=i(` Well, hats off to the chef.`,-1),c[671]||=a(`blockquote`,null,[a(`p`,null,`好吧，向厨师致敬。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/165.mp3`}),c[672]||=i(),c[673]||=a(`strong`,null,`Monica Geller:`,-1),c[674]||=i(` I-I-I’m sorry, your-your mouth was full, I didn’t hear what you said. Umm, hats off to who now?`,-1),c[675]||=a(`blockquote`,null,[a(`p`,null,`对不起，你满嘴都是，我没听见你说什么。嗯，现在向谁脱帽致敬？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/166.mp3`}),c[676]||=i(),c[677]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[678]||=i(` The chef!`,-1),c[679]||=a(`blockquote`,null,[a(`p`,null,`厨师！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/167.mp3`}),c[680]||=i(),c[681]||=a(`strong`,null,`Monica Geller:`,-1),c[682]||=i(` That’s right.`,-1),c[683]||=a(`blockquote`,null,[a(`p`,null,`没错。`)],-1),c[684]||=a(`hr`,null,null,-1),c[685]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Chandler's, Chandler and Phoebe are still working on his interviewing techniques.`)],-1),c[686]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和钱德勒、钱德勒和菲比仍在研究他的面试技巧。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/168.mp3`}),c[687]||=i(),c[688]||=a(`strong`,null,`Chandler Bing:`,-1),c[689]||=i(` …I think you’ll find if I come to work here, I don’t micro-manage. I don’t shy away from delegating.`,-1),c[690]||=a(`blockquote`,null,[a(`p`,null,`……我想你会发现，如果我来这里工作，我不会进行微观管理。我不会回避授权。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/169.mp3`}),c[691]||=i(),c[692]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[693]||=i(` Um-hmm, that’s good to know. But let’s stop focusing on what you don’t do, and start focusing on what you do do.`,-1),c[694]||=a(`blockquote`,null,[a(`p`,null,`嗯，很高兴知道。但是让我们停止关注你没有做的事情，开始关注你做的事情。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/170.mp3`}),c[695]||=i(),c[696]||=a(`strong`,null,`Chandler Bing:`,-1),c[697]||=i(` (suppressing a smile) What I do do…is manage to uh, create an atmosphere of support for the people working with me.`,-1),c[698]||=a(`blockquote`,null,[a(`p`,null,`（忍住微笑）我所做的……就是设法，呃，为和我一起工作的人营造一种支持的气氛。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/171.mp3`}),c[699]||=i(),c[700]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[701]||=i(` I see. Nice sidestep on the do do thing by the way.`,-1),c[702]||=a(`blockquote`,null,[a(`p`,null,`我明白了。顺便说一句，你在做事情的过程中做得很好。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/172.mp3`}),c[703]||=i(),c[704]||=a(`strong`,null,`Chandler Bing:`,-1),c[705]||=i(` Hardest thing I’ve ever done in my life.`,-1),c[706]||=a(`blockquote`,null,[a(`p`,null,`我这辈子做过的最难的事。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/173.mp3`}),c[707]||=i(),c[708]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[709]||=i(` You gotta go!`,-1),c[710]||=a(`blockquote`,null,[a(`p`,null,`你得走了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/174.mp3`}),c[711]||=i(),c[712]||=a(`strong`,null,`Chandler Bing:`,-1),c[713]||=i(` Oh! (Stands up.)`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`噢！（站起来）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/175.mp3`}),c[715]||=i(),c[716]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[717]||=i(` Okay, don’t worry. You’re ready.`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,`好的，别担心，你准备好了。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/176.mp3`}),c[719]||=i(),c[720]||=a(`strong`,null,`Chandler Bing:`,-1),c[721]||=i(` Really?`,-1),c[722]||=a(`blockquote`,null,[a(`p`,null,`真的吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/177.mp3`}),c[723]||=i(),c[724]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[725]||=i(` Absolutely! Just fight all your natural instincts and you’ll be great.`,-1),c[726]||=a(`blockquote`,null,[a(`p`,null,`当然！只要和你所有的本能抗争，你就会变得很棒。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/178.mp3`}),c[727]||=i(),c[728]||=a(`strong`,null,`Chandler Bing:`,-1),c[729]||=i(` Okay.`,-1),c[730]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),c[731]||=a(`hr`,null,null,-1),c[732]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Cooking Class, everyone has finished baking a batch of cookies and the teacher is going around tasting them.`)],-1),c[733]||=a(`blockquote`,null,[a(`p`,null,`【场景：烹饪课上，每个人都烤好了一批饼干，老师正在四处品尝。】`)],-1),r(p,{src:`/audio/friends/S08/S08E21/179.mp3`}),c[734]||=i(),c[735]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[736]||=i(` Ah Monica, my star student.`,-1),c[737]||=a(`blockquote`,null,[a(`p`,null,`啊，莫妮卡，我的明星学生。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/180.mp3`}),c[738]||=i(),c[739]||=a(`strong`,null,`Monica Geller:`,-1),c[740]||=i(` Y’know, you called me that before so I-I took the liberty of fashioning a star out of aluminum foil. Now, no pressure, you like my cookies, you give me the star. (Hands it to her.)`,-1),c[741]||=a(`blockquote`,null,[a(`p`,null,`你知道，你以前这么叫我，所以我——我冒昧地用铝箔做了一个星星。现在，没有压力，你喜欢我的饼干，你就把星星给我。（把它交给她。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/181.mp3`}),c[742]||=i(),c[743]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[744]||=i(` (tasting the cookie and with her mouthful) Oh, yum-yum-yum. (Hands the star back.)`,-1),c[745]||=a(`blockquote`,null,[a(`p`,null,`（品尝着饼干，满口都是）哦，好吃。（把星星还给我。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/182.mp3`}),c[746]||=i(),c[747]||=a(`strong`,null,`Monica Geller:`,-1),c[748]||=i(` Wow! A star! (The class glares at her.) I know you all hate me and-and I’m sorry, but I don’t care.`,-1),c[749]||=a(`blockquote`,null,[a(`p`,null,`哇！一个明星！（全班同学瞪着她。）我知道你们都恨我，我很抱歉，但我不在乎。`)],-1),c[750]||=a(`p`,null,[a(`em`,null,`(The teacher goes to Joey’s station.)`)],-1),c[751]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（老师去乔伊的车站。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/183.mp3`}),c[752]||=i(),c[753]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[754]||=i(` Okay Joey, you’re up next. (Tries one of his cookies.) This are good! This is amazing! You get an A!`,-1),c[755]||=a(`blockquote`,null,[a(`p`,null,`好的，乔伊，你是下一个。（试了试他的饼干。）这很好！这太棒了！你得了A！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/184.mp3`}),c[756]||=i(),c[757]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[758]||=i(` I can an A? In-in school? (To Joey) Hey, I’m a dork.`,-1),c[759]||=a(`blockquote`,null,[a(`p`,null,`我在学校能考A吗？（对乔伊）嘿，我是个笨蛋。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/185.mp3`}),c[760]||=i(),c[761]||=a(`strong`,null,`Monica Geller:`,-1),c[762]||=i(` Joey! I’m so proud of you!`,-1),c[763]||=a(`blockquote`,null,[a(`p`,null,`乔伊！我真为你骄傲！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/186.mp3`}),c[764]||=i(),c[765]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[766]||=i(` I think you should give him your star.`,-1),c[767]||=a(`blockquote`,null,[a(`p`,null,`我想你应该把你的星星给他。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/187.mp3`}),c[768]||=i(),c[769]||=a(`strong`,null,`Monica Geller:`,-1),c[770]||=i(` Excuse me? He doesn’t even know what he’s doing!`,-1),c[771]||=a(`blockquote`,null,[a(`p`,null,`对不起？他甚至不知道自己在做什么！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/188.mp3`}),c[772]||=i(),c[773]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[774]||=i(` We’re all beginners here. Nobody knows what they’re doing.`,-1),c[775]||=a(`blockquote`,null,[a(`p`,null,`我们都是初学者，没人知道他们在做什么。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/189.mp3`}),c[776]||=i(),c[777]||=a(`strong`,null,`Monica Geller:`,-1),c[778]||=i(` I do! I’m a professional chef! (The class gasps.) Oh relax! It’s not a courtroom drama!`,-1),c[779]||=a(`blockquote`,null,[a(`p`,null,`是的！我是一名专业厨师！（全班同学都屏住呼吸）哦，放松点！这不是法庭闹剧！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/190.mp3`}),c[780]||=i(),c[781]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[782]||=i(` If you’re a professional chef, what are you doing taking Introduction to Cooking?`,-1),c[783]||=a(`blockquote`,null,[a(`p`,null,`如果你是一名专业厨师，你在做什么来介绍烹饪？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/191.mp3`}),c[784]||=i(),c[785]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[786]||=i(` Yeah!`,-1),c[787]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/192.mp3`}),c[788]||=i(),c[789]||=a(`strong`,null,`Monica Geller:`,-1),c[790]||=i(` I’m-I’m sorry, it’s just that umm… Well I-I cook at this restaurant, Alessandro’s, and umm I just got a really bad review…`,-1),c[791]||=a(`blockquote`,null,[a(`p`,null,`对不起，只是…我在亚历山德罗的这家餐厅做饭，我刚收到一份很糟糕的评论…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/193.mp3`}),c[792]||=i(),c[793]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[794]||=i(` Oh Alessandro’s! I love that place!`,-1),c[795]||=a(`blockquote`,null,[a(`p`,null,`哦，亚历山德罗！我喜欢那个地方！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/194.mp3`}),c[796]||=i(),c[797]||=a(`strong`,null,`Monica Geller:`,-1),c[798]||=i(` You do?`,-1),c[799]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/195.mp3`}),c[800]||=i(),c[801]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[802]||=i(` Oh yes! You’re an excellent chef! As a person you’re a little…`,-1),c[803]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！你是一位出色的厨师！作为一个人，你有点…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/196.mp3`}),c[804]||=i(),c[805]||=a(`strong`,null,`Monica Geller:`,-1),c[806]||=i(` Oh, I’m totally crazy, but you-you like the food?`,-1),c[807]||=a(`blockquote`,null,[a(`p`,null,`哦，我真是疯了，但是你喜欢这里的食物吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/197.mp3`}),c[808]||=i(),c[809]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[810]||=i(` Very much.`,-1),c[811]||=a(`blockquote`,null,[a(`p`,null,`非常喜欢。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/198.mp3`}),c[812]||=i(),c[813]||=a(`strong`,null,`Monica Geller:`,-1),c[814]||=i(` Okay then, I don’t stink. I’m a good chef. Okay. (Starts to leave.)`,-1),c[815]||=a(`blockquote`,null,[a(`p`,null,`那好吧，我不臭。我是个好厨师。好吧。（开始离开。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/199.mp3`}),c[816]||=i(),c[817]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[818]||=i(` Whoa-whoa-whoa-whoa! I don’t want to go. I’m having fun.`,-1),c[819]||=a(`blockquote`,null,[a(`p`,null,`我不想去，我玩得很开心。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/200.mp3`}),c[820]||=i(),c[821]||=a(`strong`,null,`The Cooking Teacher:`,-1),c[822]||=i(` Well actually, did either of you pay for this class?`,-1),c[823]||=a(`blockquote`,null,[a(`p`,null,`嗯，事实上，你们有谁付过这门课的费用吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/201.mp3`}),c[824]||=i(),c[825]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[826]||=i(` Hey-hey-hey, if my friend says it’s time to go, it’s time to go. (Starts to leave, but comes back for his cookies.)`,-1),c[827]||=a(`blockquote`,null,[a(`p`,null,`嘿，嘿，如果我朋友说该走了，该走了。（开始离开，但回来拿他的饼干。）`)],-1),c[828]||=a(`hr`,null,null,-1),c[829]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`An Office Building, Chandler is on his interview.`)],-1),c[830]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`一栋办公楼，钱德勒正在接受采访。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/202.mp3`}),c[831]||=i(),c[832]||=a(`strong`,null,`Chandler Bing:`,-1),c[833]||=i(` …also I was the point person on my company’s transition from the KL-5 to GR-6 system.`,-1),c[834]||=a(`blockquote`,null,[a(`p`,null,`……我也是公司从KL-5系统过渡到GR-6系统的关键人物。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/203.mp3`}),c[835]||=i(),c[836]||=a(`strong`,null,`The Interviewer:`,-1),c[837]||=i(` You must’ve had your hands full.`,-1),c[838]||=a(`blockquote`,null,[a(`p`,null,`你一定忙得不可开交。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/204.mp3`}),c[839]||=i(),c[840]||=a(`strong`,null,`Chandler Bing:`,-1),c[841]||=i(` That I did. That I did.`,-1),c[842]||=a(`blockquote`,null,[a(`p`,null,`我做到了，我做到了。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/205.mp3`}),c[843]||=i(),c[844]||=a(`strong`,null,`The Interviewer:`,-1),c[845]||=i(` So let’s talk a little bit about your duties.`,-1),c[846]||=a(`blockquote`,null,[a(`p`,null,`那么让我们谈谈你的职责。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/206.mp3`}),c[847]||=i(),c[848]||=a(`strong`,null,`Chandler Bing:`,-1),c[849]||=i(` (nervous) My duties? (Trying not to crack a joke) All right.`,-1),c[850]||=a(`blockquote`,null,[a(`p`,null,`（紧张）我的职责？（尽量不开玩笑）好吧。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/207.mp3`}),c[851]||=i(),c[852]||=a(`strong`,null,`The Interviewer:`,-1),c[853]||=i(` Now you’ll be heading a whole division, so you’ll have a lot of duties.`,-1),c[854]||=a(`blockquote`,null,[a(`p`,null,`现在你将领导整个部门，所以你有很多职责。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/208.mp3`}),c[855]||=i(),c[856]||=a(`strong`,null,`Chandler Bing:`,-1),c[857]||=i(` (trying not to laugh) I see.`,-1),c[858]||=a(`blockquote`,null,[a(`p`,null,`（尽量不笑）我明白了。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/209.mp3`}),c[859]||=i(),c[860]||=a(`strong`,null,`The Interviewer:`,-1),c[861]||=i(` But there’ll be perhaps 30 people under you so you can dump a certain amount on them.`,-1),c[862]||=a(`blockquote`,null,[a(`p`,null,`但是你手下可能有30个人，所以你可以在他们身上撒下一定的钱。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/210.mp3`}),c[863]||=i(),c[864]||=a(`strong`,null,`Chandler Bing:`,-1),c[865]||=i(` (really try not to laugh) Good to know.`,-1),c[866]||=a(`blockquote`,null,[a(`p`,null,`（真的尽量不笑）很高兴知道。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/211.mp3`}),c[867]||=i(),c[868]||=a(`strong`,null,`The Interviewer:`,-1),c[869]||=i(` We can go into detail…`,-1),c[870]||=a(`blockquote`,null,[a(`p`,null,`我们可以详细谈谈…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/212.mp3`}),c[871]||=i(),c[872]||=a(`strong`,null,`Chandler Bing:`,-1),c[873]||=i(` No don’t I beg of you!`,-1),c[874]||=a(`blockquote`,null,[a(`p`,null,`不，我求你了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/213.mp3`}),c[875]||=i(),c[876]||=a(`strong`,null,`The Interviewer:`,-1),c[877]||=i(` All right then, we’ll have a definite answer for you on Monday, but I think I can say with some confidence, you’ll fit in well here.`,-1),c[878]||=a(`blockquote`,null,[a(`p`,null,`好吧，我们周一会给你一个明确的答案，但我想我可以自信地说，你会很适合这里的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/214.mp3`}),c[879]||=i(),c[880]||=a(`strong`,null,`Chandler Bing:`,-1),c[881]||=i(` (relieved) Really?!`,-1),c[882]||=a(`blockquote`,null,[a(`p`,null,`（松了一口气）真的吗？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/215.mp3`}),c[883]||=i(),c[884]||=a(`strong`,null,`The Interviewer:`,-1),c[885]||=i(` Absolutely. (They walk to the door.) You can relax; you did great.`,-1),c[886]||=a(`blockquote`,null,[a(`p`,null,`当然。（他们走到门口）你可以放松，你做得很好。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/216.mp3`}),c[887]||=i(),c[888]||=a(`strong`,null,`Chandler Bing:`,-1),c[889]||=i(` Yeah I gotta say thank you, I was really nervous. Y’know I’ve been told I come on to strong, make to many jokes, and then it was really hard to sidestep that duty thing. (The interviewer doesn’t understand) Duties. (Still doesn’t.) Duties! (Still doesn’t.) Poo. (Still doesn’t.)`,-1),c[890]||=a(`blockquote`,null,[a(`p`,null,`是的，我得说谢谢你，我真的很紧张。你知道我被告知我变得坚强了，开了很多玩笑，然后我真的很难逃避责任。（面试官不明白）责任。（仍然不知道。）责任！（仍然不知道。）呸。（仍然不知道。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/217.mp3`}),c[891]||=i(),c[892]||=a(`strong`,null,`The Interviewer:`,-1),c[893]||=i(` Poo?`,-1),c[894]||=a(`blockquote`,null,[a(`p`,null,`呸？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/218.mp3`}),c[895]||=i(),c[896]||=a(`strong`,null,`Chandler Bing:`,-1),c[897]||=i(` Oh my God this doesn’t count! Okay? The interview was over, that was the real Chandler Bing in there, this is just some crazy guy out in the hall! Call security! There’s a crazy guy out in the hall!`,-1),c[898]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，这不算！好吗？采访结束了，那是真正的钱德勒·宾，这只是大厅里的某个疯子！叫保安！大厅里有个疯子！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/219.mp3`}),c[899]||=i(),c[900]||=a(`strong`,null,`The Interviewer:`,-1),c[901]||=i(` Poo?!`,-1),c[902]||=a(`blockquote`,null,[a(`p`,null,`呸？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/220.mp3`}),c[903]||=i(),c[904]||=a(`strong`,null,`Chandler Bing:`,-1),c[905]||=i(` I’ll look forward to your call. (Walks away.)`,-1),c[906]||=a(`blockquote`,null,[a(`p`,null,`我等着你的电话。（走开。）`)],-1),c[907]||=a(`hr`,null,null,-1),c[908]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross and Rachel's, Ross is returning from his date.`)],-1),c[909]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯和瑞秋家，罗斯约会回来了。`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/221.mp3`}),c[910]||=i(),c[911]||=a(`strong`,null,`Ross Geller:`,-1),c[912]||=i(` Hey.`,-1),c[913]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/222.mp3`}),c[914]||=i(),c[915]||=a(`strong`,null,`Rachel Green:`,-1),c[916]||=i(` Hi! You’re back from your date!`,-1),c[917]||=a(`blockquote`,null,[a(`p`,null,`嗨！你约会回来了！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/223.mp3`}),c[918]||=i(),c[919]||=a(`strong`,null,`Ross Geller:`,-1),c[920]||=i(` How are you?`,-1),c[921]||=a(`blockquote`,null,[a(`p`,null,`你好吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/224.mp3`}),c[922]||=i(),c[923]||=a(`strong`,null,`Rachel Green:`,-1),c[924]||=i(` I’m fine, but that’s not important. What’s important is how was she?`,-1),c[925]||=a(`blockquote`,null,[a(`p`,null,`我很好，但那不重要。重要的是她怎么样？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/225.mp3`}),c[926]||=i(),c[927]||=a(`strong`,null,`Ross Geller:`,-1),c[928]||=i(` Uhh, it was fun. We, we just had coffee.`,-1),c[929]||=a(`blockquote`,null,[a(`p`,null,`嗯，很有趣。我们，我们刚喝了咖啡。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/226.mp3`}),c[930]||=i(),c[931]||=a(`strong`,null,`Rachel Green:`,-1),c[932]||=i(` Oh uh-huh, uh-huh, coffee, a little rub-rub-rub under the table.`,-1),c[933]||=a(`blockquote`,null,[a(`p`,null,`哦，嗯，嗯，咖啡，在桌子底下擦一擦。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/227.mp3`}),c[934]||=i(),c[935]||=a(`strong`,null,`Ross Geller:`,-1),c[936]||=i(` What’s uh, what’s going on? Do you not, do you not like Katie?`,-1),c[937]||=a(`blockquote`,null,[a(`p`,null,`怎么了，怎么了？你不喜欢凯蒂吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/228.mp3`}),c[938]||=i(),c[939]||=a(`strong`,null,`Rachel Green:`,-1),c[940]||=i(` No! No, she’s—She was nice. I mean, she’s a little slutty, but who isn’t?`,-1),c[941]||=a(`blockquote`,null,[a(`p`,null,`不！不，她很好。我是说，她有点放荡，但谁不是呢？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/229.mp3`}),c[942]||=i(),c[943]||=a(`strong`,null,`Ross Geller:`,-1),c[944]||=i(` I liked her.`,-1),c[945]||=a(`blockquote`,null,[a(`p`,null,`我喜欢她。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/230.mp3`}),c[946]||=i(),c[947]||=a(`strong`,null,`Rachel Green:`,-1),c[948]||=i(` Of course you did Ross, you would date a gorilla if it called you Indiana Jones!`,-1),c[949]||=a(`blockquote`,null,[a(`p`,null,`当然，罗斯，如果一只叫你印第安纳琼斯的大猩猩，你会和它约会的！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/231.mp3`}),c[950]||=i(),c[951]||=a(`strong`,null,`Ross Geller:`,-1),c[952]||=i(` Did you get like a fresh batch of pregnancy hormones today?!`,-1),c[953]||=a(`blockquote`,null,[a(`p`,null,`你今天有没有得到一批新的孕激素？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/232.mp3`}),c[954]||=i(),c[955]||=a(`strong`,null,`Rachel Green:`,-1),c[956]||=i(` No! It’s just that, Kate bothered me.`,-1),c[957]||=a(`blockquote`,null,[a(`p`,null,`不！只是凯特打扰了我。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/233.mp3`}),c[958]||=i(),c[959]||=a(`strong`,null,`Ross Geller:`,-1),c[960]||=i(` Why? What was wrong with her?`,-1),c[961]||=a(`blockquote`,null,[a(`p`,null,`为什么？她怎么了？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/234.mp3`}),c[962]||=i(),c[963]||=a(`strong`,null,`Rachel Green:`,-1),c[964]||=i(` There was nothing wrong with her! All right? She was perfectly lovely!`,-1),c[965]||=a(`blockquote`,null,[a(`p`,null,`她没什么问题！好吗？她非常可爱！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/235.mp3`}),c[966]||=i(),c[967]||=a(`strong`,null,`Ross Geller:`,-1),c[968]||=i(` Okay, so what’s the matter?`,-1),c[969]||=a(`blockquote`,null,[a(`p`,null,`好吧，那怎么了？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/236.mp3`}),c[970]||=i(),c[971]||=a(`strong`,null,`Rachel Green:`,-1),c[972]||=i(` I don’t want you to date her!`,-1),c[973]||=a(`blockquote`,null,[a(`p`,null,`我不想让你和她约会！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/237.mp3`}),c[974]||=i(),c[975]||=a(`strong`,null,`Ross Geller:`,-1),c[976]||=i(` (laughs) Why? What, what are you jealous?`,-1),c[977]||=a(`blockquote`,null,[a(`p`,null,`（笑）为什么？什么，你嫉妒什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/238.mp3`}),c[978]||=i(),c[979]||=a(`strong`,null,`Rachel Green:`,-1),c[980]||=i(` Yes! And not because I want you to go out with me, but because I don’t want you to go out with anybody! Okay? I know it’s a terrible thing to even think this, and it’s completely inappropriate, but I want you to be at my constant beck and call 24 hours a day! I’m very sorry, but that is just the way that I feel.`,-1),c[981]||=a(`blockquote`,null,[a(`p`,null,`是的！不是因为我想让你和我一起出去，而是因为我不想让你和任何人出去！好吗？我知道这样想都很可怕，而且完全不合适，但我想让你听我的指挥，每天24小时打电话！我很抱歉，但这正是我的感受。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/239.mp3`}),c[982]||=i(),c[983]||=a(`strong`,null,`Ross Geller:`,-1),c[984]||=i(` Okay.`,-1),c[985]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/240.mp3`}),c[986]||=i(),c[987]||=a(`strong`,null,`Rachel Green:`,-1),c[988]||=i(` What?!`,-1),c[989]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/241.mp3`}),c[990]||=i(),c[991]||=a(`strong`,null,`Ross Geller:`,-1),c[992]||=i(` I won’t date. I’ll uh, I’ll be here, with you, all the time.`,-1),c[993]||=a(`blockquote`,null,[a(`p`,null,`我不会约会。我会，呃，我会一直在这里，和你在一起。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/242.mp3`}),c[994]||=i(),c[995]||=a(`strong`,null,`Rachel Green:`,-1),c[996]||=i(` Really? But I’m being so unreasonable.`,-1),c[997]||=a(`blockquote`,null,[a(`p`,null,`真的吗？但我太不讲理了。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/243.mp3`}),c[998]||=i(),c[999]||=a(`strong`,null,`Ross Geller:`,-1),c[1e3]||=i(` True, but you’re allowed to be unreasonable. You’re having our baby.`,-1),c[1001]||=a(`blockquote`,null,[a(`p`,null,`没错，但你可以不讲道理。你要生我们的孩子了。`)],-1),c[1002]||=a(`p`,null,[a(`em`,null,`(Pause.)`)],-1),c[1003]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（停顿。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/244.mp3`}),c[1004]||=i(),c[1005]||=a(`strong`,null,`Rachel Green:`,-1),c[1006]||=i(` (starting to cry) Oh Ross, thank you. Thank you. (They hug.)`,-1),c[1007]||=a(`blockquote`,null,[a(`p`,null,`（开始哭）哦，罗斯，谢谢。谢谢。（他们拥抱了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/245.mp3`}),c[1008]||=i(),c[1009]||=a(`strong`,null,`Ross Geller:`,-1),c[1010]||=i(` Do you feel better?`,-1),c[1011]||=a(`blockquote`,null,[a(`p`,null,`你感觉好些了吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/246.mp3`}),c[1012]||=i(),c[1013]||=a(`strong`,null,`Rachel Green:`,-1),c[1014]||=i(` No, not really. You’re pressing the baby into my bladder and now I have to pee. Sorry. (She gets up and starts for the bathroom.)`,-1),c[1015]||=a(`blockquote`,null,[a(`p`,null,`不，不是真的。你把孩子塞进我的膀胱，现在我要小便。很抱歉（她站起来开始上厕所。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/247.mp3`}),c[1016]||=i(),c[1017]||=a(`strong`,null,`Ross Geller:`,-1),c[1018]||=i(` Uh Rach?`,-1),c[1019]||=a(`blockquote`,null,[a(`p`,null,`呃，瑞秋？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/248.mp3`}),c[1020]||=i(),c[1021]||=a(`strong`,null,`Rachel Green:`,-1),c[1022]||=i(` Yeah. (Stops and starts doing the I-have-to-go-to-the-bathroom dance.)`,-1),c[1023]||=a(`blockquote`,null,[a(`p`,null,`是的。（停下来开始跳我必须去洗手间的舞。）`)],-1),r(p,{src:`/audio/friends/S08/S08E21/249.mp3`}),c[1024]||=i(),c[1025]||=a(`strong`,null,`Ross Geller:`,-1),c[1026]||=i(` Just one thing umm…`,-1),c[1027]||=a(`blockquote`,null,[a(`p`,null,`只有一件事，嗯…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/250.mp3`}),c[1028]||=i(),c[1029]||=a(`strong`,null,`Rachel Green:`,-1),c[1030]||=i(` Uh-huh.`,-1),c[1031]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/251.mp3`}),c[1032]||=i(),c[1033]||=a(`strong`,null,`Ross Geller:`,-1),c[1034]||=i(` We live together. You’re having our baby. I’m not gonna see anybody else. Are you-are you sure you don’t want something more?`,-1),c[1035]||=a(`blockquote`,null,[a(`p`,null,`我们住在一起。你要生我们的孩子了。我不会再见到别人了。你确定你不想要更多吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/252.mp3`}),c[1036]||=i(),c[1037]||=a(`strong`,null,`Rachel Green:`,-1),c[1038]||=i(` (pause) Wow! I don’t know, maybe. I’m…`,-1),c[1039]||=a(`blockquote`,null,[a(`p`,null,`（停顿）哇！我不知道，也许吧。我…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/253.mp3`}),c[1040]||=i(),c[1041]||=a(`strong`,null,`Ross Geller:`,-1),c[1042]||=i(` Oh-oh, Rach! I was just messin’ around! (She’s stunned) Like you did last night when I had to pee?`,-1),c[1043]||=a(`blockquote`,null,[a(`p`,null,`哦，瑞秋！我只是在胡闹！（她惊呆了）就像昨晚我不得不小便时你做的那样？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/254.mp3`}),c[1044]||=i(),c[1045]||=a(`strong`,null,`Rachel Green:`,-1),c[1046]||=i(` (laughs) I knew that! I knew that! I was just messin’ with you too!`,-1),c[1047]||=a(`blockquote`,null,[a(`p`,null,`（笑）我就知道！我就知道！我也只是和你开玩笑！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/255.mp3`}),c[1048]||=i(),c[1049]||=a(`strong`,null,`Ross Geller:`,-1),c[1050]||=i(` (pause) Okay. Okay. Because for a minute you said you…`,-1),c[1051]||=a(`blockquote`,null,[a(`p`,null,`（停顿）好的。可以因为有一分钟你说你…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/256.mp3`}),c[1052]||=i(),c[1053]||=a(`strong`,null,`Rachel Green:`,-1),c[1054]||=i(` Oh no-no-no-no, no!`,-1),c[1055]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，不！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/257.mp3`}),c[1056]||=i(),c[1057]||=a(`strong`,null,`Ross Geller:`,-1),c[1058]||=i(` …that you actually…`,-1),c[1059]||=a(`blockquote`,null,[a(`p`,null,`……你实际上…`)],-1),r(p,{src:`/audio/friends/S08/S08E21/258.mp3`}),c[1060]||=i(),c[1061]||=a(`strong`,null,`Rachel Green:`,-1),c[1062]||=i(` No that’s just—(Laughs)—That’s just ‘cause I’m such a good messer!`,-1),c[1063]||=a(`blockquote`,null,[a(`p`,null,`不，那只是-（笑）-那只是因为我是个很好的厨师！`)],-1),c[1064]||=a(`p`,null,[a(`em`,null,`(They both laugh. Ross sits down, but Rachel doesn’t move and is lost in thought.)`)],-1),c[1065]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们都笑了。罗斯坐了下来，但瑞秋一动不动，陷入了沉思。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/259.mp3`}),c[1066]||=i(),c[1067]||=a(`strong`,null,`Ross Geller:`,-1),c[1068]||=i(` Rach?`,-1),c[1069]||=a(`blockquote`,null,[a(`p`,null,`瑞秋？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/260.mp3`}),c[1070]||=i(),c[1071]||=a(`strong`,null,`Rachel Green:`,-1),c[1072]||=i(` Yeah?`,-1),c[1073]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/261.mp3`}),c[1074]||=i(),c[1075]||=a(`strong`,null,`Ross Geller:`,-1),c[1076]||=i(` The bathroom?`,-1),c[1077]||=a(`blockquote`,null,[a(`p`,null,`浴室？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/262.mp3`}),c[1078]||=t(` <strong>Rachel Green:</strong> Right! (Heads for the bathroom.)<blockquote><p>对！（朝浴室走去。）</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>The New School, Joey and Monica are walking down a hallway.</em></p><blockquote><p>🎬 <em>新学校，乔伊和莫妮卡走在走廊上。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E21/263.mp3`}),c[1079]||=i(),c[1080]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1081]||=i(` Well I had a great time! Learned how to bake, ate great food, that’s the first A I’ve gotten since seventh grade, and I didn’t have to sleep with the teacher this time.`,-1),c[1082]||=a(`blockquote`,null,[a(`p`,null,`我玩得很开心！我学会了如何烘焙，吃了很棒的食物，这是我从七年级以来第一次得了A，这次我不用和老师睡觉了。`)],-1),r(p,{src:`/audio/friends/S08/S08E21/264.mp3`}),c[1083]||=i(),c[1084]||=a(`strong`,null,`Monica Geller:`,-1),c[1085]||=i(` Oh, look! Acting for Beginners! Want to feel good about yourself?`,-1),c[1086]||=a(`blockquote`,null,[a(`p`,null,`哦，看！为初学者表演！想自我感觉良好吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E21/265.mp3`}),c[1087]||=i(),c[1088]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1089]||=i(` What the hell!`,-1),c[1090]||=a(`blockquote`,null,[a(`p`,null,`见鬼！`)],-1),r(p,{src:`/audio/friends/S08/S08E21/266.mp3`}),c[1091]||=i(),c[1092]||=a(`strong`,null,`Monica Geller:`,-1),c[1093]||=i(` Okay.`,-1),c[1094]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),c[1095]||=a(`p`,null,[a(`em`,null,`(They enter.)`)],-1),c[1096]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们进来了。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/267.mp3`}),c[1097]||=i(),c[1098]||=a(`strong`,null,`The Acting Teacher:`,-1),c[1099]||=i(` All right, let’s start with some basics. Can anybody tell me what the difference between upstage and downstage is?`,-1),c[1100]||=a(`blockquote`,null,[a(`p`,null,`好的，让我们从一些基础开始。有人能告诉我后台和后台的区别吗？`)],-1),c[1101]||=a(`p`,null,[a(`em`,null,`(No one can and Monica looks at Joey expectantly.)`)],-1),c[1102]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（没人能，莫妮卡期待地看着乔伊。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E21/268.mp3`}),c[1103]||=i(),c[1104]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1105]||=i(` Yeah, this was a stupid idea. (Exits.)`,-1),c[1106]||=a(`blockquote`,null,[a(`p`,null,`是啊，这是个愚蠢的主意。（退出。）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};